theorem exists_delta_of_eps {ε₀ L L' ε : ℝ}
    (hε : ε₀ < ε) (hL : 0 < L + L') :
    ∃ δ : ℝ, 0 < δ ∧ ε₀ + (L + L') * δ ≤ ε

theorem exists_delta_of_eps_flat {ε₀ L L' ε : ℝ}
    (hε : ε₀ < ε) (hL : L + L' = 0) :
    ∃ δ : ℝ, 0 < δ ∧ ε₀ + (L + L') * δ ≤ ε

theorem exists_delta_of_eps_ge {ε₀ L L' ε : ℝ}
    (h0 : 0 ≤ L) (h0' : 0 ≤ L') (hε : ε₀ < ε) :
    ∃ δ : ℝ, 0 < δ ∧ ε₀ + (L + L') * δ ≤ ε

theorem holdsSet_member {n : ℕ} {cs : List (GeoConstraint n)} {c : GeoConstraint n}
    (pts : ℕ → Pt n) (h : HoldsSet cs pts) (hmem : c ∈ cs) :
    GeoConstraint.Holds c pts
